async function fetchAllProducts() {
  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return [
    { id: 1, name: 'Laptop', price: 999 },
    { id: 2, name: 'Phone', price: 699 },
    { id: 3, name: 'Tablet', price: 499 },
    { id: 4, name: 'Headphones', price: 199 },
    { id: 5, name: 'Watch', price: 299 },
  ]
}

// Cached across requests so day-to-day browsing doesn't re-hit the DB; invalidated
// via revalidateTag('products') once the ERP/PIM sync completes.
export const getAllProducts = unstable_cache(fetchAllProducts, ['products'], {
  tags: ['products'],
})

export async function syncCatalogFromErp() {
  // Simulate a bulk resync (pricing/inventory/availability) against the upstream ERP/PIM system
  await new Promise((resolve) => setTimeout(resolve, 1500))
}

