import { revalidateTag } from 'next/cache'
import { after } from 'next/server'
import { getAllProducts, syncCatalogFromErp } from '@/lib/db'

export default async function Page() {
  const products = await getAllProducts()

  async function syncCatalog() {
    'use server'

    // Let the response return immediately; the resync and cache invalidation
    // happen after so the admin isn't blocked on thousands of SKUs updating.
    after(async () => {
      await syncCatalogFromErp()
      revalidateTag('products')
    })
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

